INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018016', 'AN1769', 'ジャビ', 'ビスコの師匠であり、マッシュルームたちの守護者である老人。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b227007-cWsN4R3a8GAo.png', NULL, NULL, '斎藤志郎', NULL, 227007, 'SUPPORTING', 62) ON CONFLICT DO NOTHING;
