INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018018', 'AN1769', '黒革', 'ウサギの仮面をかぶった護衛の軍団を率いて、ミロとビスコを追い詰める腐敗した市長。彼はビスコに対して奇妙な執着を抱いているようだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252175-cXp9CTG9aOE4.jpg', NULL, NULL, '津田健次郎', NULL, 252175, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
