INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018022', 'AN1770', '佐々木秀鳴', '好きなもの：お菓子　佐々木は宮野の高校の先輩だ。あまりトラブルを起こさない「不良」タイプだ。宮野を通じてBL漫画を知った。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b164753-AuS2lkQfZ0RA.png', '6月17日', 'O', '白井悠介', 183, 164753, 'MAIN', 2015) ON CONFLICT DO NOTHING;
