INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018063', 'AN1772', '龍守逢', '1～3組、生徒番号8番。何事においても一番を目指している少女。生徒会の会長を務めている。負けを嫌う性格で、上達への意欲が強い。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252583-tkBAc4eOIWWd.png', '8月8日', NULL, '伊瀬茉莉也', NULL, 252583, 'SUPPORTING', 34) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018064', 'AN1772', '明日ユワ', '小美の母親。自宅で裁縫師として働いており、小美のセーラー服も手作りした。ロバイ私立学園の卒業生である。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b260973-WxEeyKobjPzo.png', '8月20日', NULL, '花澤香菜', NULL, 260973, 'SUPPORTING', 34) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018065', 'AN1772', '学園長', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b261601-3N8czZbNbBZ9.png', NULL, NULL, '一城みゆ希', NULL, 261601, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018066', 'AN1772', '兎原透子', '1～3組、生徒番号2番。コミュニケーション能力が高く、明るい性格だ。クラスメートに関する噂をたくさん知っている。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b250155-jhYHqGLreSAY.jpg', '2月19日', NULL, '鬼頭明里', NULL, 250155, 'SUPPORTING', 129) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018067', 'AN1772', '神黙根子', '1～3組、生徒番号4番。彼女はいつも眠そうな顔をしていて、授業中にうたた寝をすることが多く、先生からよく注意されています。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252582-aGpYyJymSFMs.png', '6月6日', NULL, '伊藤美来', NULL, 252582, 'SUPPORTING', 66) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018068', 'AN1772', '明日花緒', '小美の妹。小学3年生。小美とそっくりだが、気性が激しい。時々、姉を励ましてくれる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b260974-YX08Hdxrw3WE.png', '2月16日', NULL, '久野美咲', NULL, 260974, 'SUPPORTING', 119) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018069', 'AN1772', '景の母', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b262097-Tqk1x0LcEqmv.png', NULL, NULL, '竹内恵美子', NULL, 262097, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018070', 'AN1772', '古城智乃', '1～3組、6番の生徒。物静かで優しい性格で、読書が大好きだ。小道からハンカチを借りたことをきっかけに、彼女と話すようになった。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b250156-hGloB8rA46bx.png', '10月3日', NULL, '若山詩音', NULL, 250156, 'SUPPORTING', 60) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018071', 'AN1772', '四条璃生奈', '1～3組、7番の生徒。試験勉強を始めるまでは、ずっとテニスに打ち込んでいた。彼女にはある種のコンプレックスがある。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252585-laZ8koCIZ7Yd.png', '8月28日', NULL, '田所あずさ', NULL, 252585, 'SUPPORTING', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018072', 'AN1772', '明日サト', '小道の父親。仕事でとても忙しく、普段はめったに家に帰ってこない。（出典：公式サイト、翻訳）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b260975-Z0kTJ7mLe2YU.png', '12月21日', NULL, '三上哲', NULL, 260975, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018073', 'AN1772', '鷲尾瞳', '1～3組、生徒番号16番。彼女はクラスで一番背の高い女子で、すでにバレーボール部の有望なメンバーとなっている。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252578-tGPR4bLxmFLR.png', '10月30日', NULL, '石上静香', NULL, 252578, 'SUPPORTING', 40) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018074', 'AN1772', '苗代靖子', '1～3組、生徒番号12番。背が高く、ほっそりとした体型の、大人びた雰囲気の少女。よく鷲尾瞳と一緒にいる。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252589-70bC4WIL1eAs.png', '2月25日', NULL, '本渡楓', NULL, 252589, 'SUPPORTING', 25) ON CONFLICT DO NOTHING;
