INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018079', 'AN1772', '水上りり', '1～3組、生徒番号13番。水泳が超得意で、関西弁を話す。授業中はあまり話さないが、小道とは気さくに話しているようだ。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252581-aDYDEXfkXbkN.png', '5月14日', NULL, '石川由依', NULL, 252581, 'SUPPORTING', 37) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018080', 'AN1772', '戸鹿野舞衣', '1～3組、生徒番号11番。彼女はクラスで一番物静かな子です。バスケットボール部の真剣で真面目なメンバーであり、着実にシュートの練習に取り組んでいます。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252586-WLxsegyHsZ7K.png', '9月26日', NULL, '白石晴香', NULL, 252586, 'SUPPORTING', 40) ON CONFLICT DO NOTHING;
