INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018100', 'AN1774', '橘日向', '橘日向は、日々苦労の絶えない32歳の会社員だ。彼と、ハンサムな親友の神宮寺司は、裸の女神によって異世界に召喚されてしまった。しかし、女神のいたずらのせいで、橘は美しい少女に変えられてしまった。 元の体を取り戻すためには、親友と共に旅に出て、魔王を倒さなければならない。', 32, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b216128-8ChibYDcK1Kw.png', NULL, NULL, '市道真央', NULL, 216128, 'MAIN', 378) ON CONFLICT DO NOTHING;
