INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018254', 'AN1779', '犬川静六', '犬川静六は、謎めいた武士であり、「オブシディアン・エイト」の一員である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b229727-A5X1zMRUeQJa.jpg', '6月22日', 'A', '新垣樽助', NULL, 229727, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
