INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018543', 'AN1790', 'ユアン', 'ユアンは、ド・ニウの右腕であり、九龍で活動する「イエロー・ヘッド」ギャングの上級幹部である。', 24, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b284334-ZldWOKNPQkx1.jpg', '4月4日', NULL, '山口智広', NULL, 284334, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
