INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018831', 'AN1810', '青井紀子', 'アシトとシュンの母親であり、一家が経営する店の店主。現在、アシトは東京に出ているため、シュンと共に愛媛に住んでいる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b239921-yRWVuv2b6RUO.png', NULL, NULL, '園崎未恵', NULL, 239921, 'SUPPORTING', 65) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018832', 'AN1810', '中野淳之介', 'ポジション：ディフェンダー　高校1年生。東京エスペリオン・ユースのトライアウトに落ちた後、金田と同じように東京武蔵野ユースに入団した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b280424-cOueKofkpNfA.jpg', '7月25日', NULL, '西山宏太朗', 163, 280424, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018833', 'AN1810', '食堂のおばちゃん', '東京シティ・エスペリオンFCの施設で働くカフェテリアのスタッフ。彼女は栗林とハナを引き合わせ、栗林がハナに食事プランを作成してもらうよう頼めるようにした。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b283406-GqextMGuPObj.jpg', NULL, NULL, 'くわばらあきら', NULL, 283406, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018834', 'AN1810', '三上', '東京武蔵野ユースの選手', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b287484-6xykIPqHjPZw.png', NULL, NULL, '丹羽正人', NULL, 287484, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018835', 'AN1810', '青井瞬', 'シュンは『アオアシ』の脇役であり、そのスピンオフ作品『アオアシ：ブラザー・フォート』の主人公である。彼はノリコの長男であり、アシトの兄で、現在はアルバイトをしている。 シュンは最近、実家の県を本拠地とするJリーグチーム「AC愛媛」のサッカー選手としてスカウトされ、入団が内定した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b239920-djbTwSHFEFwC.png', NULL, NULL, '中島ヨシキ', 180, 239920, 'SUPPORTING', 29) ON CONFLICT DO NOTHING;
