INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018837', 'AN1810', '清水誠', '東京シティ・エスペリオンFCユースAチームのミッドフィールダー／ディフェンダー。ジュニアユースチームおよびエスペリオンBチームから昇格した。高校2年生。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b283411-CJ1di1zM7JXp.jpg', NULL, NULL, '粕谷大介', NULL, 283411, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
