INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018840', 'AN1810', '弁禅醍悟', '東京シティ・エスペリオンFCのゴールキーパーコーチ、ヨット。選手歴：鎌倉体育大学附属高校 → バンドー大学 → 東京シティ・エスペリオンFC（J1） → 徳島ヴォルティス（J2）。', 34, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b275443-lKgnrGZGz3wQ.png', NULL, NULL, '稲田徹', NULL, 275443, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
